/**
 * The shared contract between the UI and `packages/policy`.
 *
 * These shapes were DERIVED from the clickable prototype, not designed up front: every field
 * exists because a screen demanded it. `packages/policy` must produce exactly these shapes, and
 * its tests assert against the data below.
 *
 * Rules that are structural, not stylistic (see docs/specs/memory-schema.md):
 *  - memory stores `ref` + `role`, never labels, names or item descriptions
 *  - beliefs store a structured scope; the English sentence is generated by `say()` at render time
 *  - `latencySeconds` is null, never 0, when no human was involved
 */

export const CATEGORIES = [
  'groceries', 'subscriptions', 'games', 'pets', 'fastfood', 'household', 'unclassified',
] as const;
export type Category = (typeof CATEGORIES)[number];

export type Ref = string;
export type Role = 'owner' | 'approver' | 'spender' | 'dependent';
export type MemberState = 'active' | 'declared' | 'invited' | 'subject' | 'revoked';

export interface Member {
  ref: Ref;
  role: Role;
  /** Lives in the deletable database. NEVER written to memory. */
  label: string;
  state: MemberState;
  approver: boolean;
  walletLimitCents?: number;
  period?: 'weekly' | 'monthly';
}

export interface Policy {
  /** The one number onboarding asks for. Everyone's floor of autonomy. */
  autoApproveCents: number;
  /** null on purpose: the middle band is PROPOSED by the agent, never configured. */
  soloCeilingCents: number | null;
  bothFloorCents: number;
  criticalCategories: Category[];
  /** Stored on each approval so escalation reuses the value it was created with. */
  deadlineHours: number;
  dependentApprovalAboveCents: number | null;
}

export interface LearningKnobs {
  confidenceFloor: number;
  minEvidence: number;
  recencyHalfLifeDays: number;
  driftTolerance: number;
  rejectedCooldownDays: number;
}

export interface House {
  id: string;
  members: Member[];
  policy: Policy;
  learning: LearningKnobs;
}

// ---------------------------------------------------------------- events

export type Outcome = 'auto' | 'approved' | 'rejected' | 'expired';
export type Quorum = 'auto' | '1-of-2' | '2-of-2' | 'all';
export type Initiator = 'member' | 'routine' | 'agent' | 'reconciliation';

export interface Decider {
  ref: Ref;
  /** The role held AT THE TIME. A later role change must not rewrite the past. */
  role: Role;
}

export interface DecisionEvent {
  id: string;
  kind: 'decision';
  week: number;
  date: string;
  category: Category;
  amountCents: number;
  quorumRequired: Quorum;
  /** Ordered. The order IS the data — the `authority` dimension reads it. */
  decidedBy: Decider[];
  outcome: Outcome;
  /** null, never 0, when nobody was asked. Averaging zeros corrupts `friction`. */
  latencySeconds: number | null;
  escalated: boolean;
  initiatedBy: Initiator;
  blobId: string;
}

export interface SpendEvent {
  id: string;
  kind: 'spend';
  week: number;
  date: string;
  category: Category;
  amountCents: number;
  /** Opaque. Its label is a belief, not a stored field. */
  recipientRef: string;
  wallet: string;
  hasApproval: boolean;
  approvalId: string | null;
  txDigest: string;
  isCommitment?: boolean;
  expectedCents?: number;
  offRhythm?: string;
}

export interface TopUpEvent {
  id: string;
  kind: 'topup';
  week: number;
  amountCents: number;
  from: 'house';
  to: Ref;
  txDigest: string;
}

// ---------------------------------------------------------------- beliefs

export type BeliefState = 'observed' | 'ratified' | 'drifting';

interface BeliefBase {
  id: string;
  version: number;
  supersedes: string | null;
  fromWeek: number;
  scope: { actor: Ref | '*'; category: Category | '*' };
  confidence: number;
  evidenceCount: number;
  evidenceIds: string[];
  state: BeliefState;
  ratifiedTx: string | null;
  blobId: string;
}

export type Belief =
  | (BeliefBase & { dimension: 'value_band'; thresholdCents: number; streak: [number, number] })
  | (BeliefBase & { dimension: 'silence'; thresholdCents: number; streak: [number, number] })
  | (BeliefBase & { dimension: 'authority'; signsFirst: [number, number] })
  | (BeliefBase & { dimension: 'friction'; rejections: number; windowWeeks: number })
  | (BeliefBase & {
      dimension: 'drift';
      statedRule: string;
      medianGapSeconds: number;
      bypassed: [number, number];
    })
  | (BeliefBase & { dimension: 'member_pattern'; sharePct: number })
  | (BeliefBase & {
      dimension: 'rhythm';
      cadence: 'weekly' | 'monthly';
      weekday: string | null;
      medianCents: number;
      variancePct: number;
      streak: [number, number];
      /** true removes matching spend from the anomaly set and turns on price-creep detection. */
      isCommitment: boolean;
    });

export type Dimension = Belief['dimension'];

export interface Proposal {
  id: string;
  beliefId: string;
  kind: 'raise' | 'lower' | 'remove' | 'add_approval';
  fromWeek: number;
  from: string;
  to: string;
  rationale: string;
  status: 'pending' | 'accepted' | 'rejected';
  /** 'supersede' writes belief v+1; 'policy' changes policy and supersedes nothing. */
  effect: 'supersede' | 'policy';
  patch?: Partial<Belief>;
  policyPatch?: Partial<Policy>;
  acceptedBy?: Ref[];
  rejectedAtWeek?: number;
  cooldownUntilWeek?: number;
}

export interface Recipient {
  category: Category;
  isCommitment: boolean;
  by: Ref | null;
  week: number | null;
}

