const START = new Date('2026-09-01T12:00:00Z');
export const dayISO = (n: number) =>
  new Date(START.getTime() + (n - 1) * 864e5).toISOString().slice(0, 10);

const roleAt = (r: Ref): Role => HOUSE.members.find((m) => m.ref === r)?.role ?? 'spender';

const mk = (
  id: string, week: number, day: number, category: Category, amountCents: number,
  quorumRequired: Quorum, by: Ref[], outcome: Outcome, lat: number,
  escalated = false, initiatedBy: Initiator = 'member',
): DecisionEvent => ({
  id, kind: 'decision', week, date: dayISO(day), category, amountCents, quorumRequired,
  decidedBy: by.map((r) => ({ ref: r, role: roleAt(r) })),
  outcome,
  latencySeconds: by.length ? lat : null,
  escalated, initiatedBy,
  blobId: `0x${id.padEnd(8, 'a')}…9f2c`,
});

