// ---------------------------------------------------------------- helpers

export const money = (cents: number) => `$${(cents / 100).toFixed(2)}`;

export const memberOf = (ref: Ref) => HOUSE.members.find((m) => m.ref === ref);

export const nameOf = (ref: Ref): string => {
  const m = memberOf(ref);
  if (!m) return 'unknown';
  return m.state === 'revoked' ? `a former ${m.role}` : m.label;
};

export const activeApprovers = () =>
  HOUSE.members.filter((m) => m.approver && m.state === 'active');

export const upTo = <T extends { week?: number; fromWeek?: number }>(items: T[], week: number) =>
  items.filter((x) => (x.week ?? x.fromWeek ?? 0) <= week);

/** All beliefs minus any id that appears as another's `supersedes`. */
export const visibleBeliefs = (week: number): Belief[] => {
  const live = upTo(BELIEFS, week);
  const superseded = new Set(live.map((b) => b.supersedes).filter(Boolean));
  return live.filter((b) => !superseded.has(b.id));
};

export const chainOf = (b: Belief): Belief[] => {
  const out = [b];
  let cur: Belief | undefined = b;
  while (cur?.supersedes) {
    const prev: Belief | undefined = BELIEFS.find((x) => x.id === cur?.supersedes);
    if (!prev) break;
    out.unshift(prev);
    cur = prev;
  }
  return out;
};

export const recipientSay = (ref: string): string => {
  const r = RECIPIENTS[ref];
  if (!r || r.category === 'unclassified') return 'unclassified recipient';
  return `${r.isCommitment ? 'standing' : 'recurring'} · ${r.category}`;
};

/**
 * The English sentence is GENERATED, never stored — storing it would immortalise a person's name
 * in a blob that cannot be deleted. Exhaustive over the discriminated union by design.
 */
export const say = (b: Belief): string => {
  const who = b.scope.actor === '*' ? 'the house' : nameOf(b.scope.actor);
  const cat = b.scope.category === '*' ? 'any category' : b.scope.category;
  switch (b.dimension) {
    case 'value_band':
      return `${who} approves alone up to ${money(b.thresholdCents)} · ${cat} · ${b.streak[0]} of ${b.streak[1]}`;
    case 'silence':
      return `Nothing under ${money(b.thresholdCents)} has ever been discussed · ${b.evidenceCount} events, zero conversations`;
    case 'authority':
      return `The house defers to ${who} on ${cat} — signs first in ${b.signsFirst[0]} of ${b.signsFirst[1]}`;
    case 'drift':
      return `The ${b.statedRule} rule is not real — the second signature lands within ${Math.round(b.medianGapSeconds / 60)} min in ${b.bypassed[0]} of ${b.bypassed[1]}`;
    case 'member_pattern':
      return `${b.sharePct}% of ${who}'s allowance goes to ${cat}`;
    case 'friction':
      return `${cat} is the only contested category — ${b.rejections} rejection in ${b.windowWeeks} weeks`;
    case 'rhythm':
      return b.isCommitment
        ? `${cat} renews ${b.cadence} at ${money(b.medianCents)} · ${b.streak[0]} of ${b.streak[1]} · a standing commitment, not a decision`
        : `${b.weekday} is ${cat} night · ${b.streak[0]} of ${b.streak[1]} weeks · ${money(b.medianCents)} ± ${money(Math.round((b.medianCents * b.variancePct) / 100))} · never discussed`;
  }
};

/** Cap decides IF approval is needed. Band decides HOW MANY signatures. */
export const capFor = (ref: Ref, week: number) => {
  const b = visibleBeliefs(week).find(
    (x) => x.dimension === 'value_band' && x.scope.actor === ref && x.state === 'ratified',
  );
  return b && b.dimension === 'value_band'
    ? { cents: b.thresholdCents, source: `personal · ${b.id}` }
    : { cents: HOUSE.policy.autoApproveCents, source: 'house number' as const };
};
